  const result = await executeMemorySearch({
    query: params.query,
    limit: params.limit ?? 5,
    type: params.type,
    scene: params.scene,
    vectorStore: this.vectorStore,
    embeddingService: this.embeddingService,
    logger: this.logger,
  });

  return {
    text: formatSearchResponse(result),
    total: result.total,
    strategy: result.strategy,
  };
}

